def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    import heapq

    times = sorted({time for start, end, _ in jobs for time in (start, end)})
    index = {time: i for i, time in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, len(graph[v]), capacity, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest distances are computed in time order because all
    # initially usable edges point forward.
    potential = [0] * n
    for u in range(n):
        for v, _, capacity, cost in graph[u]:
            if capacity and v > u:
                potential[v] = min(potential[v], potential[u] + cost)

    total_cost = 0
    flow = 0
    infinity = float("inf")

    while flow < k:
        distance = [infinity] * n
        previous = [None] * n
        distance[0] = 0
        heap = [(0, 0)]

        while heap:
            dist, u = heapq.heappop(heap)
            if dist != distance[u]:
                continue
            for edge_index, (v, _, capacity, cost) in enumerate(graph[u]):
                if capacity:
                    new_dist = dist + cost + potential[u] - potential[v]
                    if new_dist < distance[v]:
                        distance[v] = new_dist
                        previous[v] = (u, edge_index)
                        heapq.heappush(heap, (new_dist, v))

        for v in range(n):
            if distance[v] != infinity:
                potential[v] += distance[v]

        amount = k - flow
        v = n - 1
        while v != 0:
            u, edge_index = previous[v]
            amount = min(amount, graph[u][edge_index][2])
            v = u

        v = n - 1
        while v != 0:
            u, edge_index = previous[v]
            edge = graph[u][edge_index]
            total_cost += amount * edge[3]
            edge[2] -= amount
            graph[v][edge[1]][2] += amount
            v = u

        flow += amount

    return -total_cost
